/**
 * 抽象处理者基类 - 提供职责链的基础实现
 * 
 * 设计意图：
 * 1. 实现 Handler 接口，提供链管理的通用逻辑
 * 2. 采用模板方法模式，将具体处理逻辑延迟到子类实现
 * 3. 支持两种链传递策略：自动传递（默认）和手动控制传递
 * 4. 遵循里氏替换原则，子类可以安全替换父类
 */
public abstract class AbstractHandler<T> implements Handler<T> {

    /** 链中的下一个处理器 */
    protected Handler<T> next;

    @Override
    public void handle(T request) {
        // 模板方法：先执行当前处理器的业务逻辑
        boolean handled = process(request);

        // 如果当前处理器未处理请求，且链中还有后续处理器，则继续传递
        if (!handled && next != null) {
            next.handle(request);
        }
    }

    @Override
    public Handler<T> setNext(Handler<T> next) {
        this.next = next;
        return next; // 返回下一个处理器，支持链式调用
    }

    @Override
    public Handler<T> getNext() {
        return next;
    }

    /**
     * 具体处理逻辑 - 由子类实现
     * 
     * @param request 要处理的请求
     * @return true 表示请求已被处理，false 表示需要继续传递给下一个处理器
     */
    protected abstract boolean process(T request);
}"}

