{"file_path": "src/main/java/chain/Request.java", "old_string": "", "new_string": "package chain;

/**
 * 请求类 - 表示需要通过职责链处理的请求
 * 
 * 包含请求的基本信息，用于各处理器判断是否需要处理
 */
public class Request {

    /** 请求的用户 */
    private final String user;

    /** 请求的资源 */
    private final String resource;

    /** 请求的操作类型 */
    private final String action;

    /** 请求是否需要认证 */
    private final boolean needsAuthentication;

    /** 请求是否需要授权 */
    private final boolean needsAuthorization;

    /** 请求是否需要日志记录 */
    private final boolean needsLogging;

    public Request(String user, String resource, String action, 
                   boolean needsAuthentication, boolean needsAuthorization, boolean needsLogging) {
        this.user = user;
        this.resource = resource;
        this.action = action;
        this.needsAuthentication = needsAuthentication;
        this.needsAuthorization = needsAuthorization;
        this.needsLogging = needsLogging;
    }

    // Getters
    public String getUser() { return user; }
    public String getResource() { return resource; }
    public String getAction() { return action; }
    public boolean needsAuthentication() { return needsAuthentication; }
    public boolean needsAuthorization() { return needsAuthorization; }
    public boolean needsLogging() { return needsLogging; }

    @Override
    public String toString() {
        return String.format("Request[user=%s, resource=%s, action=%s, auth=%b, authz=%b, log=%b]",
                user, resource, action, needsAuthentication, needsAuthorization, needsLogging);
    }
}"}

{"file_path": "src/main/java/chain/AuthenticationHandler.java", "old_string": "", "new_string": "package chain;

/**
 * 认证处理器 - 负责用户身份验证
 * 
 * 设计意图：
 * 1. 只处理需要认证的请求（canHandle 条件判断）
 * 2. 验证用户身份的合法性
 * 3. 如果认证失败，链在此终止，不再向后传递
 * 4. 认证成功后，请求继续传递给下一个处理器
 */
public class AuthenticationHandler extends AbstractHandler<Request> {

    @Override
    protected boolean canHandle(Request request) {
        return request.needsAuthentication();
    }

    @Override
    protected void handleRequest(Request request) {
        System.out.println("[" + getHandlerName() + "] 正在验证用户身份: " + request.getUser());

        // 模拟认证逻辑：检查用户名是否合法
        if (isValidUser(request.getUser())) {
            System.out.println("[" + getHandlerName() + "] ✓ 用户认证成功！");
        } else {
            System.out.println("[" + getHandlerName() + "] ✗ 用户认证失败！拒绝请求。");
            // 认证失败，链在此终止（不调用 next.handle）
            return;
        }
    }

    /**
     * 模拟用户验证逻辑
     */
    private boolean isValidUser(String user) {
        // 简单模拟：admin 和 user1 是合法用户
        return "admin".equals(user) || "user1".equals(user);
    }
}"}

{"file_path": "src/main/java/chain/AuthorizationHandler.java", "old_string": "", "new_string": "package chain;

/**
 * 授权处理器 - 负责检查用户权限
 * 
 * 设计意图：
 * 1. 只处理需要授权的请求
 * 2. 验证用户是否有权限执行对资源的操作
 * 3. 授权失败时链终止，防止越权访问
 * 4. 与认证处理器分离，遵循单一职责原则
 */
public class AuthorizationHandler extends AbstractHandler<Request> {

    @Override
    protected boolean canHandle(Request request) {
        return request.needsAuthorization();
    }

    @Override
    protected void handleRequest(Request request) {
        System.out.println("[" + getHandlerName() + "] 正在检查用户 [" + request.getUser() + 
                         "] 对资源 [" + request.getResource() + "] 的 [" + request.getAction() + "] 权限");

        // 模拟授权逻辑：检查用户是否有权限执行该操作
        if (isAuthorized(request.getUser(), request.getResource(), request.getAction())) {
            System.out.println("[" + getHandlerName() + "] ✓ 授权通过！");
        } else {
            System.out.println("[" + getHandlerName() + "] ✗ 授权失败！拒绝访问。");
            return; // 授权失败，链终止
        }
    }

    /**
     * 模拟权限检查逻辑
     */
    private boolean isAuthorized(String user, String resource, String action) {
        // admin 拥有所有权限
        if ("admin".equals(user)) {
            return true;
        }
        // user1 只能读取资源
        if ("user1".equals(user) && "read".equals(action)) {
            return true;
        }
        return false;
    }
}"}

