import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * 日志处理器 - 负责记录请求日志
 * 
 * 设计意图：
 * 1. 只处理需要日志记录的请求
 * 2. 记录请求的详细信息，用于审计和调试
 * 3. 通常放在链的末尾，作为最后的处理步骤
 * 4. 演示职责链中"横切关注点"的处理
 */
public class LoggingHandler extends AbstractHandler<Request> {

    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    @Override
    protected boolean canHandle(Request request) {
        return request.needsLogging();
    }

    @Override
    protected void handleRequest(Request request) {
        String timestamp = LocalDateTime.now().format(FORMATTER);

        System.out.println("[" + getHandlerName() + "] ======== 日志记录开始 ========");
        System.out.println("[" + getHandlerName() + "] 时间: " + timestamp);
        System.out.println("[" + getHandlerName() + "] 用户: " + request.getUser());
        System.out.println("[" + getHandlerName() + "] 资源: " + request.getResource());
        System.out.println("[" + getHandlerName() + "] 操作: " + request.getAction());
        System.out.println("[" + getHandlerName() + "] ======== 日志记录结束 ========");
    }
}"}

