/**
 * 客户端类 - 负责组装和执行职责链
 * 
 * 设计意图：
 * 1. 展示如何构建处理器链（链式调用 setNext）
 * 2. 演示请求如何沿链传递和处理
 * 3. 包含主方法，展示完整的执行流程
 * 
 * 职责链模式的核心优势：
 * - 解耦请求发送者和接收者
 * - 动态组合处理流程，灵活调整处理顺序
 * - 遵循开闭原则，新增处理器无需修改现有代码
 * - 每个处理器职责单一，易于维护和测试
 */
public class Client {

    public static void main(String[] args) {
        System.out.println("=== 职责链模式（Chain of Responsibility）演示 ===\n");

        // 1. 创建处理器链
        // 链的顺序：认证 -> 授权 -> 日志
        Handler<Request> authHandler = new AuthenticationHandler();
        Handler<Request> authzHandler = new AuthorizationHandler();
        Handler<Request> loggingHandler = new LoggingHandler();

        // 使用链式调用构建职责链
        authHandler.setNext(authzHandler).setNext(loggingHandler);

        System.out.println("处理器链构建完成：AuthenticationHandler -> AuthorizationHandler -> LoggingHandler\n");

        // 2. 测试场景一：完整处理流程
        System.out.println("【测试1】admin 用户读取 /data 的请求（完整处理）");
        System.out.println("-".repeat(60));
        Request request1 = new Request("admin", "/data", "read", true, true, true);
        authHandler.handle(request1);

        System.out.println("\n");

        // 3. 测试场景二：认证失败
        System.out.println("【测试2】unknown 用户的请求（认证失败，链终止）");
        System.out.println("-".repeat(60));
        Request request2 = new Request("unknown", "/data", "read", true, true, true);
        authHandler.handle(request2);

        System.out.println("\n");

        // 4. 测试场景三：授权失败
        System.out.println("【测试3】user1 用户删除 /data 的请求（授权失败）");
        System.out.println("-".repeat(60));
        Request request3 = new Request("user1", "/data", "delete", true, true, true);
        authHandler.handle(request3);

        System.out.println("\n");

        // 5. 测试场景四：只记录日志的请求
        System.out.println("【测试4】只记录日志的请求（跳过认证和授权）");
        System.out.println("-".repeat(60));
        Request request4 = new Request("guest", "/public", "read", false, false, true);
        authHandler.handle(request4);

        System.out.println("\n");

        // 6. 测试场景五：user1 读取资源（授权成功）
        System.out.println("【测试5】user1 用户读取 /data 的请求（完整处理）");
        System.out.println("-".repeat(60));
        Request request5 = new Request("user1", "/data", "read", true, true, true);
        authHandler.handle(request5);

        System.out.println("\n=== 演示结束 ===");
    }
}"}

